from pathlib import Path
import base64, gzip, subprocess

PATCH_B64 = ""

patch = gzip.decompress(base64.b64decode(PATCH_B64))
Path('/tmp/slice-e.patch').write_bytes(patch)
subprocess.run(['git','apply','--check','/tmp/slice-e.patch'],check=True)
subprocess.run(['git','apply','/tmp/slice-e.patch'],check=True)

# Harden multiple-choice generation so a generated distractor can never duplicate the correct answer.
review = Path('review-engine.js')
text = review.read_text()
old = '    const choices=shuffle([correct,...distractors],r);\n'
new = '    const pool=[correct,...distractors].filter((v,i,a)=>a.indexOf(v)===i);\n    const choices=shuffle(pool,r);\n'
if old not in text and new not in text:
    raise SystemExit('review-engine choice helper did not match expected form')
if old in text:
    review.write_text(text.replace(old,new,1))

next_file=Path('docs/NEXT_SLICES.md')
n=next_file.read_text()
old_line='3. Add delayed-retrieval item generation for Day 2 / Day 7 / Day 21 reviews.'
new_line='3. **Implemented in Patch E:** fresh deterministic Day 2 / Day 7 / Day 21 delayed-retrieval reviews with Day 21 transfer evidence, retry-safe evidence IDs, and memory-layer updates only.'
if old_line in n:
    next_file.write_text(n.replace(old_line,new_line,1))
elif 'Implemented in Patch E' not in n:
    raise SystemExit('NEXT_SLICES.md did not match expected state')

print('Slice E patch applied')
